UpdateContext({var_loadVincularInspPista: true});

// 📝 Cria inspeção principal a partir do dado temporário
With(
    {
        novoRegistro: Patch(
            '7.4-tbl_InspPista',
            Defaults('7.4-tbl_InspPista'),
            LookUp(col_inspPista_mob_temp, hash = var_hash)
        )
    },

    UpdateContext({var_idInspRegister: novoRegistro});

    // 🆔 Atualiza campo ID_pk e gera protocolo
    Patch(
        '7.4-tbl_InspPista',
        novoRegistro,
        {
            ID_pk: novoRegistro.ID,
            Protocolo: varIATAUser & "-INSP-PISTA-" & novoRegistro.ID
        }
    );

    // 📋 Registra todos os itens da inspeção
    ForAll(
        col_inspPistaItens_mob_temp,
        Patch(
            '7.4.1-tbl_InspPistaItens',
            Defaults('7.4.1-tbl_InspPistaItens'),
            {
                IdInsp: novoRegistro.ID,
                Bloco: ThisRecord.Bloco,
                IATA: ThisRecord.IATA,
                Aeroporto: ThisRecord.Aeroporto,
                Local: ThisRecord.Local,
                Item: ThisRecord.Item,
                sIten: ThisRecord.sIten,
                Latitude: ThisRecord.Latitude,
                Longitude: ThisRecord.Longitude,
                Status: "Pendente",
                DataInicioApont: ThisRecord.DataInicioApont,
                HoraInicioApont: ThisRecord.HoraInicioApont,
                UsuarioCriador: ThisRecord.UsuarioCriador,
                Hash: ThisRecord.Hash,
                Foto: ThisRecord.Foto,
                Foto2: ThisRecord.Foto2,
                Foto3: ThisRecord.Foto3
            }
        )
    );

    // 🧾 Recupera os itens recém-criados para adicionar protocolo item a item
    ClearCollect(
        col_addProtocoloItens,
        Filter(
            '7.4.1-tbl_InspPistaItens',
            IdInsp = novoRegistro.ID
        )
    );

    ForAll(
        col_addProtocoloItens,
        Patch(
            '7.4.1-tbl_InspPistaItens',
            ThisRecord,
            {
                Protocolo: varIATAUser & "-INSP-PISTA-ITEM-" & ThisRecord.ID
            }
        )
    );

    // 🎤 Salva anotações de áudio, se existirem
    If(
        CountRows(col_anotacaoAudio_mob) > 0,
        ForAll(
            col_anotacaoAudio_mob,
            Patch(
                tbl_inspPistaAnotacao,
                Defaults(tbl_inspPistaAnotacao),
                {
                    ID_FK: novoRegistro.ID,
                    Audio: ThisRecord.AUDIO,
                    Local: ThisRecord.LOCAL,
                    Item: ThisRecord.ITEM,
                    SItem: ThisRecord.SITEM
                }
            )
        )
    );

    // ✅ Finaliza carregamento quando registros forem compatíveis
    If(
        CountRows(
            Filter(
                FirstN(
                    Sort(
                        '7.4.1-tbl_InspPistaItens',
                        ID,
                        SortOrder.Descending
                    ),
                    100
                ),
                IdInsp = novoRegistro.ID
            )
        ) = CountRows(GalleryResumo_7.AllItems),
        UpdateContext({var_loadVincularInspPista: false})
    )
)

